{"query":"Entire Echo browser review renderBundle renderCards renderContext active card evidence disclosure local speech voices","repo_root":"/Users/gayathriperumal/buildathon/cli","commit":"79518ac9349b6cf1e104b1a9c534c2d07a69f6fe","tree":"2bcc8a616730d0ad7618092658646317236c2e58","profile":"full","results":[{"rank":1,"score":146.2645,"file_path":"cmd/entire-echo/internal/webui/assets/app.js","start_line":137,"end_line":186,"focus_line":144,"snippet_start_line":137,"snippet_end_line":186,"symbol_start_line":137,"symbol_end_line":148,"language":"JavaScript","kind":"function","symbol_id":"local/cli:JavaScript:cmd/entire-echo/internal/webui/assets/app.js:function:renderBundle","symbol_name":"renderBundle","qualified_name":"renderBundle","signature":"function renderBundle(bundle, source)","signals":["path","body","exact-symbol","symbol-name","constraint:entity","exact-code-token","graph:callers","complete-symbol","contiguous-span"],"snippet":"  function renderBundle(bundle, source) {
    validateBundle(bundle);
    state.bundle = bundle;
    $("load-state").textContent = source === "fixture" ? "Showing the included development fixture." : "Showing review data from /api/review.";
    renderTarget(bundle.target);
    renderContext(bundle.context);
    const overview = $("overview"); overview.replaceChildren(element("p", bundle.overview.text), sourceControl(bundle.overview.evidence_ids));
    renderCards(bundle);
    const continuation = $("continuation"); continuation.replaceChildren(claimList(bundle.continuation || [], "No continuation claim was supplied."));
    renderEvidence(bundle); renderWarnings(bundle); updateSpeechControls();
    setStatus(source === "fixture" ? "Fixture review loaded." : "Review loaded.");
  }
  function showUnavailable(message) {
    state.bundle = null; state.cards = [];
    $("load-state").textContent = `Review data is unavailable: ${message}`;
    ["target", "overview", "cards", "continuation", "evidence", "warnings"].forEach((id) => $(id).replaceChildren());
    $("context-state").textContent = "Context unavailable: review data could not be loaded.";
    $("context-state").dataset.status = "unavailable";
    $("active-card").textContent = "No card is active.";
    $("warnings").append(element("p", "The text interface remains available. Select “Use included fixture” to inspect the interface with local example data.", "warning"));
    updateSpeechControls(); setStatus("Review data is unavailable.");
  }
  async function load(mode) {
    $("load-state").textContent = mode === "fixture" ? "Loading included fixture…" : "Loading review data…";
    try {
      const response = await fetch(mode === "fixture" ? "review.fixture.json" : "/api/review", { headers: { Accept: "application/json" } });
      if (!response.ok) throw new Error(`Request returned ${response.status}.`);
      renderBundle(await response.json(), mode);
    } catch (error) { showUnavailable(error instanceof Error ? error.message : "Unknown loading error."); }
  }

  function speechText(card) {
    if (!card) return "No review card is available.";
    const claims = card.claims.length ? card.claims.map((claim) => claim.text).join(" ") : "No claim was established from the available evidence.";
    const context = state.bundle && state.bundle.context;
    const qualification = context && context.status !== "complete" ? `Context ${context.status}. ${(context.reasons || []).join(" ")} ` : "";
    return `${qualification}${card.title}. ${claims}`;
  }
  function updateSpeechPreview() { $("speech-preview").textContent = `What will be spoken: ${speechText(activeCard())}`; }
  function updateSpeechControls() {
    const available = state.supported && Boolean(activeCard());
    ["read-card", "repeat", "previous-card", "next-card", "slower", "faster", "read-evidence"].forEach((id) => { $(id).disabled = !available; });
    $("pause-resume").disabled = !state.supported || !state.speaking;
    $("stop").disabled = !state.supported || !state.speaking;
    $("pause-resume").textContent = state.paused ? "Resume" : "Pause";
    $("speech-rate").textContent = `Rate: ${state.rate.toFixed(1)}×`;
    const localVoiceText = state.voices.length ? ` ${state.voices.length} local browser voice${state.voices.length === 1 ? " is" : "s are"} available.` : " No local browser voice is available.";
    $("speech-state").textContent = state.supported ? `Speech uses only local browser voices and starts only when you select a reading control.${localVoiceText}` : "Speech synthesis is unavailable in this browser. The review remains available as text.";
    updateSpeechPreview();
  }","merged_ranks":[1,2,3]},{"rank":2,"score":116.054,"file_path":"cmd/entire-echo/main.go","start_line":266,"end_line":351,"focus_line":347,"snippet_start_line":266,"snippet_end_line":351,"symbol_start_line":266,"symbol_end_line":351,"language":"Go","kind":"function","symbol_id":"local/cli:Go:cmd/entire-echo/main.go:function:build","symbol_name":"build","qualified_name":"build","signature":"func build(ctx context.Context, r CommandRunner, cwd, target string) (ReviewBundle, error)","signals":["path","body","signature","symbol-usage","complete-symbol"],"snippet":"func build(ctx context.Context, r CommandRunner, cwd, target string) (ReviewBundle, error) {
	if strings.TrimSpace(target) == "" {
		return ReviewBundle{}, errors.New("provide exactly one checkpoint ID or commit")
	}
	metaOut, metaErr, err := r.Run(ctx, "entire", []string{"checkpoint", "explain", target, "--json"}, cwd)
	if err != nil {
		return ReviewBundle{}, fmt.Errorf("checkpoint explain metadata: %w: %s", err, strings.TrimSpace(string(metaErr)))
	}
	meta, err := parseCheckpointMetadata(metaOut)
	if err != nil {
		return ReviewBundle{}, err
	}
	index, sessionID := latestSession(meta)
	b := builder{bundle: ReviewBundle{SchemaVersion: schemaVersion, Target: Target{CheckpointID: meta.CheckpointID, SessionID: sessionID}, Context: ContextCompleteness{Status: contextComplete}}}
	metaID := b.evidence("checkpoint_metadata", "checkpoint:"+meta.CheckpointID, []string{"entire", "checkpoint", "explain", target, "--json"}, string(metaOut), "confirmed")

	rootOut, _, rootRunErr := r.Run(ctx, "git", []string{"rev-parse", "--show-toplevel"}, cwd)
	root := strings.TrimSpace(string(rootOut))
	if rootRunErr != nil || root == "" {
		warnID := b.evidence("warning", "git:worktree-root", []string{"git", "rev-parse", "--show-toplevel"}, "repository root was unavailable", "question")
		b.bundle.Warnings = append(b.bundle.Warnings, Warning{Text: "Git diff unavailable: repository root could not be resolved.", EvidenceIDs: []string{warnID}})
		b.limitContext(contextPartial, "Git worktree root was unavailable, so commit and diff evidence could not be reconstructed.")
	}

	transcript, _, transcriptRunErr := r.Run(ctx, "entire", []string{"checkpoint", "explain", target, "--transcript", "--session-index", fmt.Sprint(index)}, cwd)
	if transcriptRunErr != nil || len(strings.TrimSpace(string(transcript))) == 0 {
		warnID := b.evidence("warning", "checkpoint:"+meta.CheckpointID+"/transcript", []string{"entire", "checkpoint", "explain", target, "--transcript", "--session-index", fmt.Sprint(index)}, "stored transcript was unavailable", "question")
		b.bundle.Warnings = append(b.bundle.Warnings, Warning{Text: "Transcript reconstruction unavailable.", EvidenceIDs: []string{warnID}})
		b.bundle.MissingOrUncertain = append(b.bundle.MissingOrUncertain, Claim{Text: "Requested and implemented details may be incomplete because the stored transcript was unavailable.", EvidenceIDs: []string{warnID}, Confidence: "question"})
		b.limitContext(contextUnavailable, "Stored checkpoint transcript was unavailable.")
	} else {
		transcriptID := b.evidence("checkpoint_transcript", "checkpoint:"+meta.CheckpointID+"/session:"+sessionID, []string{"entire", "checkpoint", "explain", target, "--transcript", "--session-index", fmt.Sprint(index)}, string(transcript), "confirmed")
		b.bundle.Warnings = append(b.bundle.Warnings, Warning{Text: "Transcript evidence is stored-session output; its checkpoint scope is not exposed by the public export contract.", EvidenceIDs: []string{transcriptID}})
		if transcriptRedacted(transcript) {
			b.limitContext(contextRedacted, "Stored checkpoint transcript contains redacted content.")
			b.bundle.Warnings = append(b.bundle.Warnings, Warning{Text: "Transcript evidence includes redacted content; the reconstruction is not complete.", EvidenceIDs: []string{transcriptID}})
		}
		requested, implemented := 0, 0
		for _, entry := range transcriptEntries(transcript) {
			claim := Claim{Text: "Stored transcript text: " + bound(entry.text, 240), EvidenceIDs: []string{transcriptID}, Confidence: "confirmed"}
			if entry.kind == "user" && requested < 6 {
				b.bundle.Requested = append(b.bundle.Requested, claim)
				requested++
			} else if entry.kind == "assistant" && implemented < 6 {
				b.bundle.Implemented = append(b.bundle.Implemented, claim)
				implemented++
			}
		}
		if requested == 0 {
			b.bundle.MissingOrUncertain = append(b.bundle.MissingOrUncertain, Claim{Text: "No user request could be extracted from the stored transcript.", EvidenceIDs: []string{transcriptID}, Confidence: "question"})
			b.limitContext(contextPartial, "No user request could be extracted from the stored transcript.")
		}
	}

	if root != "" {
		commit, warning := associatedCommit(ctx, r, root, meta.CheckpointID)
		if warning != "" {
			id := b.evidence("warning", "checkpoint:"+meta.CheckpointID+"/commit", []string{"git", "log", "--all", "--format=%H", "--fixed-strings", "--grep=Entire-Checkpoint: " + meta.CheckpointID}, warning, "question")
			b.bundle.Warnings = append(b.bundle.Warnings, Warning{Text: "Git diff unavailable: " + warning + ".", EvidenceIDs: []string{id}})
			b.limitContext(contextPartial, "Associated checkpoint commit could not be resolved unambiguously.")
		} else {
			b.bundle.Target.Commit = commit
			diff, _, diffRunErr := r.Run(ctx, "git", []string{"diff", "--find-renames", commit + "^", commit, "--"}, root)
			if diffRunErr != nil {
				id := b.evidence("warning", "commit:"+commit, []string{"git", "diff", "--find-renames", commit + "^", commit, "--"}, "associated commit diff was unavailable", "question")
				b.bundle.Warnings = append(b.bundle.Warnings, Warning{Text: "Git diff unavailable for associated commit.", EvidenceIDs: []string{id}})
				b.limitContext(contextPartial, "Associated commit diff was unavailable.")
			} else {
				diffID := b.evidence("git_diff", "commit:"+commit, []string{"git", "diff", "--find-renames", commit + "^", commit, "--"}, string(diff), "confirmed")
				files := uniqueStrings(append(meta.FilesTouched, changedFiles(string(diff))...))
				sort.Strings(files)
				if len(files) > 0 {
					b.bundle.Implemented = append(b.bundle.Implemented, Claim{Text: "Associated commit changes: " + strings.Join(files, ", ") + ".", EvidenceIDs: []string{diffID, metaID}, Confidence: "confirmed"})
				}
				b.graph(ctx, r, root, diffSymbols(string(diff)), diffID)
			}
		}
	}

	b.bundle.Overview = Claim{Text: fmt.Sprintf("Review of checkpoint %s, session %s.", meta.CheckpointID, sessionID), EvidenceIDs: []string{metaID}, Confidence: "confirmed"}
	b.bundle.Continuation = append(b.bundle.Continuation, Claim{Text: "Continue from the identified checkpoint and session; rerun the evidence commands recorded below before changing code.", EvidenceIDs: []string{metaID}, Confidence: "confirmed"})
	if err := validateBundle(b.bundle); err != nil {
		return ReviewBundle{}, err
	}
	return b.bundle, nil
}"},{"rank":3,"score":116.054,"file_path":"cmd/entire-echo/web.go","start_line":26,"end_line":71,"focus_line":28,"snippet_start_line":27,"snippet_end_line":71,"symbol_start_line":27,"symbol_end_line":71,"language":"Go","kind":"function","symbol_id":"local/cli:Go:cmd/entire-echo/web.go:function:newWebHandler","symbol_name":"newWebHandler","qualified_name":"newWebHandler","signature":"func newWebHandler(bundle ReviewBundle) (http.Handler, error)","signals":["path","body","signature","symbol-usage","complete-symbol"],"snippet":"func newWebHandler(bundle ReviewBundle) (http.Handler, error) {
	if err := validateBundle(bundle); err != nil {
		return nil, fmt.Errorf("invalid review bundle: %w", err)
	}
	reviewJSON, err := json.Marshal(bundle)
	if err != nil {
		return nil, fmt.Errorf("encode review bundle: %w", err)
	}

	assets := map[string]struct {
		file        string
		contentType string
	}{
		"/":                    {file: "index.html", contentType: "text/html; charset=utf-8"},
		"/app.js":              {file: "app.js", contentType: "text/javascript; charset=utf-8"},
		"/styles.css":          {file: "styles.css", contentType: "text/css; charset=utf-8"},
		"/review.fixture.json": {file: "review.fixture.json", contentType: "application/json; charset=utf-8"},
	}

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		setBrowserHeaders(w)
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		if r.URL.Path == "/api/review" {
			w.Header().Set("Content-Type", "application/json; charset=utf-8")
			_, _ = w.Write(reviewJSON)
			return
		}
		asset, ok := assets[r.URL.Path]
		if !ok {
			http.NotFound(w, r)
			return
		}
		contents, err := webAssets.ReadFile("internal/webui/assets/" + asset.file)
		if err != nil {
			http.Error(w, "embedded interface unavailable", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", asset.contentType)
		_, _ = w.Write(contents)
	}), nil
}"},{"rank":4,"score":116.054,"file_path":"cmd/entire-echo/main.go","start_line":389,"end_line":393,"focus_line":391,"snippet_start_line":390,"snippet_end_line":391,"symbol_start_line":391,"symbol_end_line":440,"language":"Go","kind":"function","symbol_id":"local/cli:Go:cmd/entire-echo/main.go:function:validateBundle","symbol_name":"validateBundle","qualified_name":"validateBundle","signature":"func validateBundle(bundle ReviewBundle) error","signals":["path","body","symbol-name","signature","symbol-usage"],"snippet":"
