		"/review.fixture.json": {file: "review.fixture.json", contentType: "application/json; charset=utf-8"},
	}

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		setBrowserHeaders(w)
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		if r.URL.Path == "/api/review" {
			w.Header().Set("Content-Type", "application/json; charset=utf-8")
			_, _ = w.Write(reviewJSON)
			return
		}
		asset, ok := assets[r.URL.Path]
		if !ok {
			http.NotFound(w, r)
			return
		}
		contents, err := webAssets.ReadFile("internal/webui/assets/" + asset.file)
		if err != nil {
			http.Error(w, "embedded interface unavailable", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", asset.contentType)
		_, _ = w.Write(contents)
	}), nil
}"},{"rank":4,"score":116.054,"file_path":"cmd/entire-echo/main.go","start_line":389,"end_line":393,"focus_line":391,"snippet_start_line":390,"snippet_end_line":391,"symbol_start_line":391,"symbol_end_line":440,"language":"Go","kind":"function","symbol_id":"local/cli:Go:cmd/entire-echo/main.go:function:validateBundle","symbol_name":"validateBundle","qualified_name":"validateBundle","signature":"func validateBundle(bundle ReviewBundle) error","signals":["path","body","symbol-name","signature","symbol-usage"],"snippet":"
